"""The three tools the agent can call, their JSON schemas, and argument validation."""
import json
import re
from pathlib import Path

STORE_PATH = Path(__file__).resolve().parent.parent / "data" / "store.json"
ORDER_ID = re.compile(r"^A\d{4}$")
TRACKING_ID = re.compile(r"^TRK-\d{6}$")

# Tool definitions in the shape the Anthropic Messages API expects.
TOOLS = [
    {
        "name": "get_order",
        "description": "Look up one order by its id (format A1234). Returns status, items, total and tracking number.",
        "input_schema": {
            "type": "object",
            "properties": {"order_id": {"type": "string", "description": "Order id like A1001"}},
            "required": ["order_id"],
            "additionalProperties": False,
        },
    },
    {
        "name": "track_shipment",
        "description": "Get carrier status for a tracking number (format TRK-123456). Use get_order first to find it.",
        "input_schema": {
            "type": "object",
            "properties": {"tracking_number": {"type": "string"}},
            "required": ["tracking_number"],
            "additionalProperties": False,
        },
    },
    {
        "name": "search_policy",
        "description": "Search store policies (returns, shipping, damaged items, cancellations) by keywords.",
        "input_schema": {
            "type": "object",
            "properties": {"query": {"type": "string", "description": "A few keywords"}},
            "required": ["query"],
            "additionalProperties": False,
        },
    },
]


class ToolError(Exception):
    """Raised for bad arguments or missing records. Sent back to the model as is_error."""


def load_store(path=STORE_PATH):
    return json.loads(Path(path).read_text(encoding="utf-8"))


def validate(name, args):
    """Check the arguments against the schema before touching any data."""
    spec = next((t for t in TOOLS if t["name"] == name), None)
    if spec is None:
        raise ToolError(f"unknown tool: {name}")
    if not isinstance(args, dict):
        raise ToolError("arguments must be an object")
    schema = spec["input_schema"]
    missing = [k for k in schema["required"] if k not in args]
    extra = [k for k in args if k not in schema["properties"]]
    if missing or extra:
        raise ToolError(f"missing={missing} unexpected={extra}")
    for key, value in args.items():
        if not isinstance(value, str) or not value.strip():
            raise ToolError(f"{key} must be a non-empty string")
    if name == "get_order" and not ORDER_ID.match(args["order_id"]):
        raise ToolError("order_id must look like A1234")
    if name == "track_shipment" and not TRACKING_ID.match(args["tracking_number"]):
        raise ToolError("tracking_number must look like TRK-123456")
    if name == "search_policy" and len(args["query"]) > 200:
        raise ToolError("query too long")


def get_order(store, order_id):
    order = store["orders"].get(order_id)
    if order is None:
        raise ToolError(f"no order {order_id}")
    return {"order_id": order_id, **order}


def track_shipment(store, tracking_number):
    shipment = store["shipments"].get(tracking_number)
    if shipment is None:
        raise ToolError(f"no shipment {tracking_number}")
    return {"tracking_number": tracking_number, **shipment}


def _words(text):
    """Lowercase words longer than 2 letters, with a crude plural/past-tense trim."""
    return {re.sub(r"(ed|s)$", "", w) for w in re.findall(r"[a-z]+", text.lower()) if len(w) > 2}


def search_policy(store, query):
    words = _words(query)
    scored = []
    for p in store["policies"]:
        text_words = _words(p["title"] + " " + p["text"])
        score = len(words & text_words) + (3 if p["id"] in words else 0)
        if score:
            scored.append((score, p))
    scored.sort(key=lambda pair: -pair[0])
    return {"results": [p for _, p in scored[:2]]}


FUNCTIONS = {"get_order": get_order, "track_shipment": track_shipment, "search_policy": search_policy}


def execute_tool(store, name, args):
    """Validate, run, and return (result_text, is_error). Never raises."""
    try:
        validate(name, args)
        result = FUNCTIONS[name](store, **args)
        return json.dumps(result), False
    except ToolError as exc:
        return f"Error: {exc}", True

"""Two interchangeable model clients: the real Anthropic API, and an offline fake.

Both expose create(system, messages, tools) and return an object with
.stop_reason and .content (a list of blocks with .type), like the SDK does.
"""
import json
import os
import re
from types import SimpleNamespace


class RealLLM:
    def __init__(self):
        import anthropic  # imported here so fake mode works without the package

        self.model = os.environ.get("MODEL")
        if not self.model:
            raise RuntimeError("Set MODEL (see .env.example) to use LLM_MODE=real")
        self.client = anthropic.Anthropic()  # reads ANTHROPIC_API_KEY

    def create(self, system, messages, tools):
        return self.client.messages.create(
            model=self.model, max_tokens=16000, system=system, tools=tools, messages=messages
        )


TRACK_WORDS = {"where", "track", "tracking", "arrive", "eta", "delivered"}
POLICY_WORDS = {"return", "refund", "policy", "cancel", "damaged", "broken", "shipping"}


def _results_so_far(messages):
    """Map tool name -> (parsed result or None, is_error) from the conversation."""
    names, out = {}, {}
    for msg in messages:
        if isinstance(msg["content"], str):
            continue
        for block in msg["content"]:
            kind = block["type"] if isinstance(block, dict) else block.type
            if kind == "tool_use":
                names[block.id] = block.name
            elif kind == "tool_result":
                ok = not block.get("is_error", False)
                out[names[block["tool_use_id"]]] = (json.loads(block["content"]) if ok else None, not ok)
    return out


class FakeLLM:
    """Rule-based stand-in that emits the same block shapes as the real API."""

    def create(self, system, messages, tools):
        question = messages[0]["content"]
        words = set(re.findall(r"[a-z]+", question.lower()))
        order_ids = re.findall(r"\bA\d{4}\b", question)
        done = _results_so_far(messages)
        call_id = f"toolu_fake_{len(messages)}"

        def tool(name, **args):
            block = SimpleNamespace(type="tool_use", id=call_id, name=name, input=args)
            return SimpleNamespace(stop_reason="tool_use", content=[block])

        if order_ids and "get_order" not in done:
            return tool("get_order", order_id=order_ids[0])
        order, order_err = done.get("get_order", (None, False))
        if words & TRACK_WORDS and order and order.get("tracking") and "track_shipment" not in done:
            return tool("track_shipment", tracking_number=order["tracking"])
        if words & POLICY_WORDS and "search_policy" not in done:
            return tool("search_policy", query=question[:200])

        lines = []
        if order_err:
            lines.append("I could not find that order. Please double-check the order id.")
        elif order:
            lines.append(f"Order {order['order_id']} is {order['status']} ({', '.join(order['items'])}).")
        ship = done.get("track_shipment", (None, False))[0]
        if ship:
            lines.append(f"{ship['carrier']} shows it {ship['status']}, last scan {ship['last_scan']}, ETA {ship['eta']}.")
        policy = done.get("search_policy", (None, False))[0]
        if policy and policy["results"]:
            top = policy["results"][0]
            lines.append(f"Policy ({top['title']}): {top['text']}")
        if not lines:
            lines.append("I can help with orders, shipments and store policies. What is your order id?")
        return SimpleNamespace(stop_reason="end_turn", content=[SimpleNamespace(type="text", text=" ".join(lines))])


def make_llm():
    return RealLLM() if os.environ.get("LLM_MODE", "fake") == "real" else FakeLLM()

"""The agent loop: ask the model, run the tools it requests, repeat until done or capped."""
import json
import time

from agent.tools import TOOLS, execute_tool, load_store

SYSTEM = (
    "You are an order-support agent for an online store. Use the tools to look up facts; "
    "never guess order status, tracking or policy details. If a tool returns an error, "
    "tell the customer plainly what is missing. Keep answers to 2-4 sentences."
)


class Trace:
    """Collects one JSON event per step; optionally appends them to a .jsonl file."""

    def __init__(self, path=None):
        self.path, self.events = path, []

    def log(self, kind, **data):
        event = {"t": round(time.time(), 3), "kind": kind, **data}
        self.events.append(event)
        if self.path:
            with open(self.path, "a", encoding="utf-8") as f:
                f.write(json.dumps(event) + "\n")


def run_agent(question, llm, store=None, max_iterations=6, trace=None):
    store = store or load_store()
    trace = trace or Trace()
    messages = [{"role": "user", "content": question}]
    trace.log("user", text=question)

    for step in range(1, max_iterations + 1):
        response = llm.create(system=SYSTEM, messages=messages, tools=TOOLS)
        trace.log("model", step=step, stop_reason=response.stop_reason)
        # Keep the assistant turn exactly as returned (it may hold tool_use and thinking blocks).
        messages.append({"role": "assistant", "content": response.content})

        if response.stop_reason != "tool_use":
            text = " ".join(b.text for b in response.content if b.type == "text").strip()
            if response.stop_reason != "end_turn":
                text = text or f"Stopped early ({response.stop_reason}). A human will follow up."
            trace.log("final", step=step, text=text)
            return {"answer": text, "steps": step, "messages": messages, "trace": trace.events}

        results = []
        for block in response.content:
            if block.type != "tool_use":
                continue
            output, is_error = execute_tool(store, block.name, block.input)
            trace.log("tool", step=step, name=block.name, input=block.input, is_error=is_error, output=output[:300])
            results.append({"type": "tool_result", "tool_use_id": block.id, "content": output, "is_error": is_error})
        messages.append({"role": "user", "content": results})  # all results in ONE user message

    trace.log("capped", max_iterations=max_iterations)
    answer = "Sorry, I could not finish this request. I have passed it to a human agent."
    return {"answer": answer, "steps": max_iterations, "messages": messages, "trace": trace.events}

"""A tiny in-memory mock CRM. Plain Python, no MCP here, so it is easy to unit test."""
from datetime import date

CUSTOMERS = {
    "C001": {"name": "Acme Test Co", "industry": "manufacturing", "stage": "customer", "arr": 120000, "owner": "Sam"},
    "C002": {"name": "Globex Sample Ltd", "industry": "logistics", "stage": "trial", "arr": 0, "owner": "Priya"},
    "C003": {"name": "Initech Demo Inc", "industry": "software", "stage": "negotiation", "arr": 45000, "owner": "Sam"},
    "C004": {"name": "Umbrella Example LLC", "industry": "healthcare", "stage": "churned", "arr": 0, "owner": "Lee"},
}
NOTES = {"C001": ["Renewal due in November."], "C003": ["Asked for SSO before signing."]}


def reset():
    """Restore the starting notes (used by tests)."""
    NOTES.clear()
    NOTES.update({"C001": ["Renewal due in November."], "C003": ["Asked for SSO before signing."]})


def search(query: str, limit: int = 5) -> list[dict]:
    q = query.lower().strip()
    hits = [
        {"id": cid, **c}
        for cid, c in CUSTOMERS.items()
        if q in c["name"].lower() or q == c["industry"] or q == c["stage"]
    ]
    return hits[: max(1, min(limit, 20))]


def get(customer_id: str) -> dict:
    if customer_id not in CUSTOMERS:
        raise ValueError(f"Unknown customer id {customer_id!r}. Use search_customers first.")
    return {"id": customer_id, **CUSTOMERS[customer_id], "notes": NOTES.get(customer_id, [])}


def add_note(customer_id: str, text: str) -> dict:
    get(customer_id)  # raises for unknown ids
    text = text.strip()
    if not 1 <= len(text) <= 500:
        raise ValueError("Note must be 1 to 500 characters.")
    NOTES.setdefault(customer_id, []).append(f"{date.today().isoformat()}: {text}")
    return {"id": customer_id, "notes": NOTES[customer_id]}


def pipeline_summary() -> str:
    lines = ["# Pipeline summary"]
    for stage in ["trial", "negotiation", "customer", "churned"]:
        names = [c["name"] for c in CUSTOMERS.values() if c["stage"] == stage]
        lines.append(f"- {stage}: {len(names)} ({', '.join(names) or 'none'})")
    total = sum(c["arr"] for c in CUSTOMERS.values())
    lines.append(f"\nTotal ARR: ${total:,}")
    return "\n".join(lines)

"""MCP server exposing the mock CRM: 3 tools + 1 resource, over stdio.

Run directly:     python crm_server.py        (waits silently for an MCP client)
Inspect it:       npx @modelcontextprotocol/inspector python crm_server.py
"""
import logging
import sys

from mcp.server.fastmcp import FastMCP

import crm_data

# stdout carries the MCP protocol. Anything you print there corrupts it, so log to stderr.
logging.basicConfig(stream=sys.stderr, level=logging.INFO)
log = logging.getLogger("mock-crm")

mcp = FastMCP("mock-crm")


@mcp.tool()
def search_customers(query: str, limit: int = 5) -> list[dict]:
    """Find customers by part of their name, or by exact industry or stage
    (trial, negotiation, customer, churned). Returns id, name, stage, ARR, owner."""
    log.info("search_customers %r", query)
    return crm_data.search(query, limit)


@mcp.tool()
def get_customer(customer_id: str) -> dict:
    """Get one customer's full record and notes by id (like C001)."""
    return crm_data.get(customer_id)


@mcp.tool()
def add_note(customer_id: str, text: str) -> dict:
    """Append a short note (max 500 chars) to a customer. This changes data."""
    log.info("add_note %s", customer_id)
    return crm_data.add_note(customer_id, text)


@mcp.resource("crm://pipeline/summary")
def pipeline_summary() -> str:
    """Read-only markdown summary of the sales pipeline by stage."""
    return crm_data.pipeline_summary()


if __name__ == "__main__":
    mcp.run()  # stdio transport by default

