"""Embedders. The hashing one is deterministic and offline; the real one downloads a model."""
import hashlib
import os
import re

import numpy as np

STOP = set("a an the of to in on for and or is are be by with at from as it that this your you i we our do does can how what when who which much many any per".split())


def tokens(text):
    """Lowercase words minus stopwords, with a crude plural trim (days -> day)."""
    words = re.findall(r"[a-z0-9]+", text.lower())
    return [re.sub(r"(?<=[a-z]{3})s$", "", w) for w in words if w not in STOP]


class HashingEmbedder:
    """Feature hashing of words and word pairs into a fixed-size unit vector.

    Not semantic (it will not know "vacation" means "PTO"), but deterministic,
    instant, and good enough to test the whole pipeline without downloads.
    """

    def __init__(self, dim=1024):
        self.dim = dim

    def _bucket(self, feature):
        h = int(hashlib.md5(feature.encode()).hexdigest(), 16)
        return h % self.dim, (1.0 if (h >> 64) & 1 else -1.0)

    def embed(self, texts):
        out = np.zeros((len(texts), self.dim), dtype=np.float32)
        for row, text in enumerate(texts):
            toks = tokens(text)
            feats = toks + [a + "_" + b for a, b in zip(toks, toks[1:])]
            for f in feats:
                idx, sign = self._bucket(f)
                out[row, idx] += sign
            norm = np.linalg.norm(out[row])
            if norm:
                out[row] /= norm
        return out


class SentenceTransformerEmbedder:
    """Real semantic embeddings. Needs: pip install sentence-transformers (large download)."""

    def __init__(self, name=None):
        from sentence_transformers import SentenceTransformer

        self.model = SentenceTransformer(name or os.environ.get("EMBED_MODEL", "all-MiniLM-L6-v2"))

    def embed(self, texts):
        return np.asarray(self.model.encode(texts, normalize_embeddings=True), dtype=np.float32)


def make_embedder():
    mode = os.environ.get("EMBED_MODE", "hash")
    return SentenceTransformerEmbedder() if mode == "st" else HashingEmbedder()

"""Ingest -> chunk -> embed -> store, and retrieval with an ACL filter."""
from dataclasses import dataclass
from pathlib import Path

import numpy as np

DOCS_DIR = Path(__file__).resolve().parent.parent / "docs"


@dataclass
class Chunk:
    id: str      # "pto#1"
    doc_id: str  # "pto"
    title: str
    acl: str     # "all", "hr", "finance"
    text: str


def load_docs(folder=DOCS_DIR):
    """Read markdown files with a small front-matter header (title, acl)."""
    docs = []
    for path in sorted(Path(folder).glob("*.md")):
        _, header, body = path.read_text(encoding="utf-8").split("---", 2)
        meta = dict(line.split(":", 1) for line in header.strip().splitlines())
        meta = {k.strip(): v.strip() for k, v in meta.items()}
        docs.append({"id": path.stem, "title": meta["title"], "acl": meta.get("acl", "all"), "body": body.strip()})
    return docs


def chunk_doc(doc, max_chars=400):
    """Split on blank lines, then pack paragraphs into chunks up to max_chars."""
    chunks, current = [], ""
    for para in [p.strip() for p in doc["body"].split("\n\n") if p.strip()]:
        if current and len(current) + len(para) > max_chars:
            chunks.append(current)
            current = ""
        current = (current + "\n\n" + para).strip()
    if current:
        chunks.append(current)
    return [Chunk(f"{doc['id']}#{i}", doc["id"], doc["title"], doc["acl"], text) for i, text in enumerate(chunks)]


class InMemoryStore:
    """Numpy fallback for pgvector: a matrix of unit vectors plus metadata."""

    def __init__(self):
        self.chunks, self.vectors = [], None

    def add(self, chunks, vectors):
        self.chunks.extend(chunks)
        self.vectors = vectors if self.vectors is None else np.vstack([self.vectors, vectors])

    def search(self, query_vec, k, allowed_acls):
        # Filter BEFORE ranking so forbidden text can never reach the prompt.
        allowed = np.array([c.acl in allowed_acls for c in self.chunks])
        scores = self.vectors @ query_vec          # cosine similarity (vectors are normalized)
        scores = np.where(allowed, scores, -np.inf)
        order = np.argsort(-scores)[:k]
        return [(self.chunks[i], float(scores[i])) for i in order if np.isfinite(scores[i])]


def build_index(embedder, folder=DOCS_DIR):
    store = InMemoryStore()
    chunks = [c for doc in load_docs(folder) for c in chunk_doc(doc)]
    # Prefix the title so each chunk carries its context ("contextual chunk header").
    store.add(chunks, embedder.embed([f"{c.title}. {c.text}" for c in chunks]))
    return store


def retrieve(store, embedder, question, groups, k=3):
    allowed = {"all", *groups}
    return store.search(embedder.embed([question])[0], k, allowed)

